// GPU skinning in the GPU scene: see include/fuse/renderer/skinning/skinning_gpu.hpp.
#include <fuse/renderer/skinning/skinning_gpu.hpp>

#include <fuse/renderer/vk/allocator.hpp>
#include <fuse/renderer/vk/device.hpp>
#include <fuse/renderer/vk/upload_queue.hpp>

#include <algorithm>
#include <cstring>

#if defined(FUSE_VULKAN_BACKEND)
#include <vulkan/vulkan.h>

// Generated by cmake/rp_skinning.cmake from shaders/skinning/*: kSkinLbs{Slang,Glsl}Spv and FUSE_SKINNING_{SLANG,GLSL}.
#include "skinning_spv.h"
#endif

namespace fuse::renderer::skinning {

namespace {
constexpr u64 kRestStride = 64u;   ///< position + normal + weights
constexpr u64 kOutStride = 48u;    ///< current + previous position + normal
constexpr u64 kMatrixBytes = 64u;
constexpr u64 kAlign = 256u;

[[maybe_unused]] u64 alignUp(u64 v, u64 a) { return (v + a - 1u) & ~(a - 1u); }

[[maybe_unused]] BufferUsage usage(std::initializer_list<BufferUsage> bits) {
    u32 u = 0;
    for (const BufferUsage b : bits) {
        u |= static_cast<u32>(b);
    }
    return static_cast<BufferUsage>(u);
}

struct Code {
    const u32* words = nullptr;
    usize bytes = 0;
    const char* language = "none";
};

[[maybe_unused]] Code kernelCode(SkinningKernelLanguage language) {
#if defined(FUSE_SKINNING_SLANG)
    if (language == SkinningKernelLanguage::Auto || language == SkinningKernelLanguage::Slang) {
        return Code{kSkinLbsSlangSpv, sizeof(kSkinLbsSlangSpv), "slang"};
    }
#endif
#if defined(FUSE_SKINNING_GLSL)
    if (language == SkinningKernelLanguage::Auto || language == SkinningKernelLanguage::Glsl) {
        return Code{kSkinLbsGlslSpv, sizeof(kSkinLbsGlslSpv), "glsl"};
    }
#endif
    (void)language;
    return Code{};
}
} // namespace

SkinningGpu::~SkinningGpu() { destroy(); }

bool SkinningGpu::init(const SkinningGpuDesc& desc) {
    destroy();
    m_desc = desc;
#if defined(FUSE_VULKAN_BACKEND)
    if (desc.device == nullptr || desc.allocator == nullptr || desc.upload == nullptr || desc.framesInFlight == 0u ||
        desc.maxRestVertices == 0u || desc.maxOutputVertices == 0u || desc.maxInstances == 0u || desc.maxPaletteBones == 0u) {
        return false;
    }
    const RendererCaps& caps = desc.device->info().caps;
    if (!caps.bufferDeviceAddress || !caps.shaderInt64) {
        return false;
    }
    const Code code = kernelCode(desc.language);
    if (code.words == nullptr) {
        return false;
    }
    m_initialized = true; // destroy() releases partial state from here on
    m_language = code.language;
    m_paletteOffset = alignUp(static_cast<u64>(desc.maxInstances) * sizeof(SkinJob), kAlign);
    m_slotBytes = alignUp(m_paletteOffset + 2u * static_cast<u64>(desc.maxPaletteBones) * kMatrixBytes, kAlign);

    BufferDesc rest{};
    rest.size = static_cast<usize>(static_cast<u64>(desc.maxRestVertices) * kRestStride);
    rest.usage = usage({BufferUsage::Storage, BufferUsage::ShaderDeviceAddress, BufferUsage::TransferDst});
    rest.memoryUsage = MemoryUsage::GpuOnly;
    rest.name = "skinning.rest";
    BufferDesc out{};
    out.size = static_cast<usize>(static_cast<u64>(desc.maxOutputVertices) * kOutStride);
    out.usage = usage({BufferUsage::Storage, BufferUsage::ShaderDeviceAddress, BufferUsage::TransferSrc});
    out.memoryUsage = MemoryUsage::GpuOnly;
    out.name = "skinning.out";
    BufferDesc ring{};
    ring.size = static_cast<usize>(m_slotBytes * desc.framesInFlight);
    ring.usage = usage({BufferUsage::Storage, BufferUsage::ShaderDeviceAddress});
    ring.memoryUsage = MemoryUsage::CpuToGpu;
    ring.name = "skinning.ring";
    if (!desc.allocator->createBuffer(rest, m_rest) || m_rest.deviceAddress == 0u ||
        !desc.allocator->createBuffer(out, m_out) || m_out.deviceAddress == 0u ||
        !desc.allocator->createBuffer(ring, m_ring) || m_ring.deviceAddress == 0u || m_ring.mapped == nullptr) {
        destroy();
        return false;
    }

    const VkDevice vk = static_cast<VkDevice>(desc.device->nativeHandle());
    VkPushConstantRange range{VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(SkinPush)};
    VkPipelineLayoutCreateInfo layoutInfo{};
    layoutInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
    layoutInfo.pushConstantRangeCount = 1;
    layoutInfo.pPushConstantRanges = &range;
    VkPipelineLayout layout = VK_NULL_HANDLE;
    if (vkCreatePipelineLayout(vk, &layoutInfo, nullptr, &layout) != VK_SUCCESS) {
        destroy();
        return false;
    }
    m_layout = layout;
    VkShaderModuleCreateInfo moduleInfo{};
    moduleInfo.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
    moduleInfo.codeSize = code.bytes;
    moduleInfo.pCode = code.words;
    VkShaderModule module = VK_NULL_HANDLE;
    if (vkCreateShaderModule(vk, &moduleInfo, nullptr, &module) != VK_SUCCESS) {
        destroy();
        return false;
    }
    VkComputePipelineCreateInfo info{};
    info.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
    info.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
    info.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
    info.stage.module = module;
    info.stage.pName = "main";
    info.layout = layout;
    VkPipeline pipeline = VK_NULL_HANDLE;
    const VkResult result = vkCreateComputePipelines(vk, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
    vkDestroyShaderModule(vk, module, nullptr);
    if (result != VK_SUCCESS) {
        destroy();
        return false;
    }
    m_pipeline = pipeline;

    const usize paletteFloats = static_cast<usize>(desc.maxPaletteBones) * 16u;
    m_pose.assign(paletteFloats, 0.f);
    m_last.assign(paletteFloats, 0.f);
    m_prevWritten.assign(paletteFloats, 0.f);
    m_meshes.reserve(64u);
    m_instances.reserve(desc.maxInstances);
    return true;
#else
    return false;
#endif
}

void SkinningGpu::destroy() {
    if (!m_initialized) {
        return;
    }
#if defined(FUSE_VULKAN_BACKEND)
    const VkDevice vk = static_cast<VkDevice>(m_desc.device->nativeHandle());
    if (m_pipeline != nullptr) {
        vkDestroyPipeline(vk, static_cast<VkPipeline>(m_pipeline), nullptr);
    }
    if (m_layout != nullptr) {
        vkDestroyPipelineLayout(vk, static_cast<VkPipelineLayout>(m_layout), nullptr);
    }
#endif
    m_pipeline = nullptr;
    m_layout = nullptr;
    Buffer* buffers[3] = {&m_rest, &m_out, &m_ring};
    for (Buffer* b : buffers) {
        if (b->handle != nullptr) {
            m_desc.allocator->destroyBuffer(*b);
        }
        *b = Buffer{};
    }
    m_meshes.clear();
    m_instances.clear();
    m_pose.clear();
    m_last.clear();
    m_prevWritten.clear();
    m_restUsed = m_outUsed = m_bonesUsed = m_maxInstanceVertices = 0;
    m_jobsAddress = 0;
    m_lastPaletteAddress = 0;
    m_jobCount = 0;
    m_language = "none";
    m_stats = SkinningStats{};
    m_initialized = false;
}

void SkinningGpu::attach(gpu_scene::GpuScene& scene) {
    if (m_initialized) {
        scene.setDynamicGeometry(m_out.handle, m_out.desc.size);
    }
}

u32 SkinningGpu::addMesh(const SkinMeshDesc& d) {
    if (!m_initialized || d.restPositions == nullptr || d.weights == nullptr || d.vertexCount == 0u ||
        d.vertexCount > m_desc.maxRestVertices - m_restUsed) {
        return kInvalidSkin;
    }
    const u32 n = d.vertexCount;
    // pos + nrm (f32 x 4) then weights (32 B): 64 B / vertex, staged section by section.
    std::vector<f32> block(static_cast<usize>(n) * 8u, 0.f);
    for (u32 v = 0; v < n; ++v) {
        block[v * 4u + 0u] = d.restPositions[v * 3u + 0u];
        block[v * 4u + 1u] = d.restPositions[v * 3u + 1u];
        block[v * 4u + 2u] = d.restPositions[v * 3u + 2u];
        block[v * 4u + 3u] = d.handedness != nullptr && d.handedness[v] < 0.f ? -1.f : 1.f;
        if (d.restNormals != nullptr) {
            f32* nrm = &block[(static_cast<usize>(n) + v) * 4u];
            nrm[0] = d.restNormals[v * 3u + 0u];
            nrm[1] = d.restNormals[v * 3u + 1u];
            nrm[2] = d.restNormals[v * 3u + 2u];
        }
    }
    const u64 base = static_cast<u64>(m_restUsed) * kRestStride;
    usize staged = 0;
    if (!m_desc.upload->stage(block.data(), block.size() * sizeof(f32), staged) ||
        !m_desc.upload->recordBufferCopy(m_rest.handle, staged, static_cast<usize>(base), block.size() * sizeof(f32))) {
        return kInvalidSkin;
    }
    const usize weightBytes = static_cast<usize>(n) * sizeof(SkinVertexWeights);
    if (!m_desc.upload->stage(d.weights, weightBytes, staged) ||
        !m_desc.upload->recordBufferCopy(m_rest.handle, staged, static_cast<usize>(base + static_cast<u64>(n) * 32u),
                                         weightBytes)) {
        return kInvalidSkin;
    }
    MeshRecord m{};
    m.restVertex = m_restUsed;
    m.vertexCount = n;
    m.normals = d.restNormals != nullptr;
    m_restUsed += n;
    m_meshes.push_back(m);
    return static_cast<u32>(m_meshes.size() - 1u);
}

u32 SkinningGpu::addInstance(gpu_scene::GpuScene& scene, const SkinInstanceDesc& d) {
    if (!m_initialized || d.mesh >= m_meshes.size() || d.baseMeshRow >= scene.meshCount() || d.boneCount == 0u ||
        m_instances.size() >= m_desc.maxInstances || d.boneCount > m_desc.maxPaletteBones - m_bonesUsed ||
        !scene.alive(d.instance)) {
        return kInvalidSkin;
    }
    const MeshRecord& mesh = m_meshes[d.mesh];
    const gpu_scene::GpuMesh& base = scene.mesh(d.baseMeshRow);
    if (base.vertexCount != mesh.vertexCount || mesh.vertexCount > m_desc.maxOutputVertices - m_outUsed) {
        return kInvalidSkin;
    }
    InstanceRecord r{};
    r.mesh = d.mesh;
    r.outVertex = m_outUsed;
    r.vertexCount = mesh.vertexCount;
    r.paletteBone = m_bonesUsed;
    r.boneCount = d.boneCount;
    gpu_scene::GpuMesh row = base;
    const u64 out = m_out.deviceAddress + static_cast<u64>(r.outVertex) * kOutStride;
    row.positions = out;
    row.flags |= gpu_scene::kMeshFloatPositions | gpu_scene::kMeshSkinned;
    if (mesh.normals) {
        row.normals = out + 2u * static_cast<u64>(mesh.vertexCount) * gpu_scene::kFloatVertexStride;
        row.flags |= gpu_scene::kMeshFloatNormals;
    }
    if (d.boundsRadius > 0.f) {
        row.boundsCenter[0] = d.boundsCenter[0];
        row.boundsCenter[1] = d.boundsCenter[1];
        row.boundsCenter[2] = d.boundsCenter[2];
        row.boundsRadius = d.boundsRadius;
    } else {
        row.boundsRadius = base.boundsRadius * d.boundsScale;
    }
    r.meshRow = scene.addMesh(row);
    if (r.meshRow == gpu_scene::kInvalidIndex || !scene.setInstanceMesh(d.instance, r.meshRow)) {
        return kInvalidSkin;
    }
    // Identity palette until the first setPose.
    for (u32 b = 0; b < d.boneCount; ++b) {
        f32* m = &m_pose[(static_cast<usize>(r.paletteBone) + b) * 16u];
        std::memset(m, 0, 16u * sizeof(f32));
        m[0] = m[5] = m[10] = m[15] = 1.f;
    }
    m_outUsed += mesh.vertexCount;
    m_bonesUsed += d.boneCount;
    m_maxInstanceVertices = std::max(m_maxInstanceVertices, mesh.vertexCount);
    m_instances.push_back(r);
    ++m_stats.meshRows;
    m_stats.instances = static_cast<u32>(m_instances.size());
    return static_cast<u32>(m_instances.size() - 1u);
}

bool SkinningGpu::setPose(u32 skin, const f32* palette, u32 boneCount) {
    if (!m_initialized || skin >= m_instances.size() || palette == nullptr || boneCount != m_instances[skin].boneCount) {
        return false;
    }
    std::memcpy(&m_pose[static_cast<usize>(m_instances[skin].paletteBone) * 16u], palette,
                static_cast<usize>(boneCount) * 16u * sizeof(f32));
    return true;
}

void SkinningGpu::resetHistory(u32 skin) {
    if (skin < m_instances.size()) {
        m_instances[skin].history = false;
    }
}

bool SkinningGpu::beginFrame(u64 frameSerial) {
    m_stats.dispatches = 0;
    m_jobCount = 0;
    if (!m_initialized) {
        return false;
    }
    const u64 slot = (frameSerial % m_desc.framesInFlight) * m_slotBytes;
    u8* mapped = static_cast<u8*>(m_ring.mapped) + slot;
    SkinJob* jobs = reinterpret_cast<SkinJob*>(mapped);
    f32* palettes = reinterpret_cast<f32*>(mapped + m_paletteOffset);
    const u64 paletteAddress = m_ring.deviceAddress + slot + m_paletteOffset;
    const u64 prevBase = static_cast<u64>(m_desc.maxPaletteBones) * 16u; // floats: the previous palettes' half
    // The previous palette is normally read where the previous frame wrote it (its ring slot is intact: the ring has
    // framesInFlight slots and only this slot is rewritten), so only this frame's palettes cross the bus. When the
    // previous frame used this same slot (repeated serial), the previous palettes are uploaded into its second half.
    const bool lastSlotUsable = m_lastPaletteAddress != 0u && m_lastPaletteAddress != paletteAddress;
    const usize used = static_cast<usize>(m_bonesUsed) * 16u;
    std::memcpy(palettes, m_pose.data(), used * sizeof(f32)); // instances' palettes are contiguous, in order
    u32 vertices = 0;
    for (u32 i = 0; i < m_instances.size(); ++i) {
        InstanceRecord& r = m_instances[i];
        const MeshRecord& mesh = m_meshes[r.mesh];
        const usize first = static_cast<usize>(r.paletteBone) * 16u;
        const usize floats = static_cast<usize>(r.boneCount) * 16u;
        const f32* cur = &m_pose[first];
        const bool history = r.history;
        std::memcpy(&m_prevWritten[first], history ? &m_last[first] : cur, floats * sizeof(f32));
        u64 prevAddress = paletteAddress + first * sizeof(f32); // no history: the current palette
        if (history && lastSlotUsable) {
            prevAddress = m_lastPaletteAddress + first * sizeof(f32);
        } else if (history) {
            std::memcpy(palettes + prevBase + first, &m_prevWritten[first], floats * sizeof(f32));
            prevAddress = paletteAddress + (prevBase + first) * sizeof(f32);
        }
        r.history = true;
        SkinJob j{};
        j.rest = m_rest.deviceAddress + static_cast<u64>(mesh.restVertex) * kRestStride;
        j.palette = paletteAddress + first * sizeof(f32);
        j.prevPalette = prevAddress;
        j.out = m_out.deviceAddress + static_cast<u64>(r.outVertex) * kOutStride;
        j.vertexCount = r.vertexCount;
        j.boneCount = r.boneCount;
        j.flags = mesh.normals ? kSkinJobNormals : 0u;
        jobs[i] = j;
        vertices += r.vertexCount;
    }
    std::memcpy(m_last.data(), m_pose.data(), used * sizeof(f32));
    m_lastPaletteAddress = paletteAddress;
    m_jobCount = static_cast<u32>(m_instances.size());
    m_jobsAddress = m_ring.deviceAddress + slot;
    m_stats.jobs = m_jobCount;
    m_stats.vertices = vertices;
    return true;
}

void SkinningGpu::addSkinning(rg::Graph& graph, const gpu_scene::GpuSceneGraphRefs& scene) {
    if (!m_initialized || m_jobCount == 0u || !scene.dynamicGeometry.valid()) {
        return;
    }
    m_record = PassRecord{};
    m_record.self = this;
    m_record.push.jobs = m_jobsAddress;
    m_record.push.jobCount = m_jobCount;
    m_record.groupsX = (m_maxInstanceVertices + kSkinWorkgroup - 1u) / kSkinWorkgroup;
    rg::PassBuilder pass = graph.addPass("skin.lbs", &SkinningGpu::recordSkinning, &m_record);
    pass.use(scene.dynamicGeometry, rg::Access::StorageWrite, {}, rg::kStageCompute);
    pass.neverCull();
    ++m_stats.dispatches;
}

void SkinningGpu::recordSkinning(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const PassRecord& r = *static_cast<const PassRecord*>(user);
    const SkinningGpu& self = *r.self;
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipeline>(self.m_pipeline));
    vkCmdPushConstants(cmd, static_cast<VkPipelineLayout>(self.m_layout), VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(SkinPush),
                       &r.push);
    vkCmdDispatch(cmd, r.groupsX, r.push.jobCount, 1u);
#else
    (void)context;
    (void)user;
#endif
}

} // namespace fuse::renderer::skinning
